\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{array}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\pagestyle{empty}

% ── Dark Data Theme ──
\definecolor{primary}{HTML}{0F172A}
\definecolor{secondary}{HTML}{3B82F6}
\definecolor{accent}{HTML}{10B981}
\definecolor{highlight}{HTML}{F59E0B}
\definecolor{cardbg}{HTML}{1E293B}
\definecolor{cardborder}{HTML}{334155}
\definecolor{textwhite}{HTML}{F1F5F9}
\definecolor{textgray}{HTML}{94A3B8}
\definecolor{statbg}{HTML}{172554}
\definecolor{tablehdr}{HTML}{1D4ED8}
\definecolor{airowa}{HTML}{172554}
\definecolor{airowb}{HTML}{1E3A5F}
\definecolor{nairowa}{HTML}{1E293B}
\definecolor{nairowb}{HTML}{253549}
\definecolor{themebg1}{HTML}{172554}
\definecolor{themebg2}{HTML}{1C1917}
\definecolor{themebg3}{HTML}{064E3B}
\definecolor{themebg4}{HTML}{1E1B4B}

\pagecolor{primary}
\color{textwhite}

\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}

\tcbset{
  darkcard/.style={
    enhanced, arc=3pt, boxrule=1pt, colframe=cardborder, colback=cardbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=cardbg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=1pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.3},
  },
  greencard/.style={
    enhanced, arc=3pt, boxrule=1pt, colframe=cardborder, colback=cardbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardbg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=1pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.3},
  },
  ambercard/.style={
    enhanced, arc=3pt, boxrule=1pt, colframe=cardborder, colback=cardbg,
    borderline west={5pt}{0pt}{highlight},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{highlight},
    coltitle=highlight, colbacktitle=cardbg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=1pt, titlerule style={highlight!50},
    valign=top, drop shadow={opacity=0.3},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=3mm},
]

% ══════════════════════════════════════════════════════
%  TITLE BAR
% ══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=20pt, bottom=12pt,
  halign=center, valign=center,
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{72}{86}\selectfont\bfseries\color{textwhite} GitHub's Hottest Repos: AI Agents Dominate}\\[14pt]
  {\fontsize{32}{40}\selectfont\color{textgray} A 24-Hour Snapshot of Open-Source Momentum}\\[6pt]
  {\fontsize{28}{36}\selectfont\color{secondary} Data via OSSInsight\enspace$\bullet$\enspace 10.6 Billion+ GitHub Events Tracked in Real Time}
}

% ══════════════════════════════════════════════════════
%  STATS BANNER
% ══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!95!black, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=8pt, bottom=8pt,
  valign=center,
]{name=stats, column=1, span=3, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.3\linewidth}\centering
    \fcolorbox{secondary!60}{statbg}{\parbox{0.86\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{highlight} 10.6B+}\\[6pt]
      {\fontsize{24}{30}\selectfont\color{textgray} GitHub Events Tracked}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.3\linewidth}\centering
    \fcolorbox{accent!60}{statbg}{\parbox{0.86\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{accent} 826★}\\[6pt]
      {\fontsize{24}{30}\selectfont\color{textgray} Top Repo Stars (24h)}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.3\linewidth}\centering
    \fcolorbox{highlight!60}{statbg}{\parbox{0.86\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{highlight} 70\%}\\[6pt]
      {\fontsize{24}{30}\selectfont\color{textwhite} AI/Agent Repos in Top 20}\vspace{8pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════════════════
%  TOP 20 TABLE (centerpiece)
% ══════════════════════════════════════════════════════
\posterbox[
  darkcard, title={Top 20 Trending Repositories (Past 24 Hours)},
]{name=table, column=1, span=3, between=row5 and row13}{
  \centering
  \renewcommand{\arraystretch}{1.55}%
  \fontsize{26}{34}\selectfont\color{textwhite}%
  \begin{tabular}{
    >{\centering\arraybackslash}p{0.045\linewidth}
    p{0.35\linewidth}
    >{\centering\arraybackslash}p{0.12\linewidth}
    >{\centering\arraybackslash}p{0.10\linewidth}
    >{\centering\arraybackslash}p{0.10\linewidth}
    >{\centering\arraybackslash}p{0.10\linewidth}
    >{\centering\arraybackslash}p{0.10\linewidth}
  }
  \rowcolor{tablehdr}
  \color{textwhite}\bfseries Rank &
  \color{textwhite}\bfseries Repository &
  \color{textwhite}\bfseries Language &
  \color{textwhite}\bfseries Stars &
  \color{textwhite}\bfseries Forks &
  \color{textwhite}\bfseries Pushes &
  \color{textwhite}\bfseries PRs \\
  \noalign{\hrule height 1.5pt}
  % ── AI rows ──
  \rowcolor{airowa} \color{highlight}\bfseries \#1 & \color{accent}forrestchang/andrej-karpathy-skills & --- & 826 & 79 & 0 & 0 \\
  \rowcolor{airowb} \color{highlight}\bfseries \#2 & \color{accent}NousResearch/hermes-agent & Python & 468 & 102 & 66 & 61 \\
  \rowcolor{nairowa} \#3 & NawfalMotii79/PLFM\_RADAR & Verilog & 353 & 81 & 5 & 0 \\
  \rowcolor{airowa} \#4 & \color{accent}thedotmack/claude-mem & TypeScript & 335 & 33 & 4 & 0 \\
  \rowcolor{nairowb} \#5 & VoltAgent/awesome-design-md & HTML & 321 & 49 & 0 & 0 \\
  \rowcolor{airowa} \#6 & \color{accent}JuliusBrussee/caveman & Python & 237 & 19 & 0 & 3 \\
  \rowcolor{airowb} \#7 & \color{accent}multica-ai/multica & TypeScript & 139 & 13 & 44 & 10 \\
  \rowcolor{airowa} \#8 & \color{accent}safishamsi/graphify & Python & 120 & 13 & 0 & 1 \\
  \rowcolor{airowb} \#9 & \color{accent}jamiepine/voicebox & TypeScript & 100 & 12 & 8 & 3 \\
  \rowcolor{airowa} \#10 & \color{accent}lsdefine/GenericAgent & Python & 101 & 9 & 5 & 2 \\
  \rowcolor{airowb} \#11 & \color{accent}rohitg00/ai-eng-from-scratch & Python & 82 & 19 & 0 & 0 \\
  \rowcolor{nairowa} \#12 & EvoMap/evolver & JavaScript & 95 & 5 & 1 & 1 \\
  \rowcolor{airowa} \#13 & \color{accent}google/magika & Python & 122 & 7 & 0 & 3 \\
  \rowcolor{airowb} \#14 & \color{accent}vercel-labs/open-agents & TypeScript & 84 & 12 & 2 & 12 \\
  \rowcolor{nairowa} \#15 & thunderbird/thunderbolt & TypeScript & 82 & 4 & 7 & 0 \\
  \rowcolor{airowa} \#16 & \color{accent}alchaincyf/nuwa-skill & Python & 67 & 17 & 0 & 0 \\
  \rowcolor{nairowb} \#17 & BasedHardware/omi & Dart & 111 & 72 & 9 & 7 \\
  \rowcolor{airowa} \#18 & \color{accent}farion1231/cc-switch & Rust & 77 & 6 & 5 & 0 \\
  \rowcolor{nairowa} \#19 & SimoneAvogadro/android-re-skill & Shell & 77 & 0 & 0 & 0 \\
  \rowcolor{airowb} \#20 & \color{accent}rtk-ai/rtk & Rust & 73 & 4 & 2 & 1 \\
  \noalign{\hrule height 1.5pt}
  \multicolumn{7}{l}{%
    \fontsize{22}{28}\selectfont
    \color{accent}$\blacksquare$\enspace AI/Agent-related\hspace{24pt}%
    \color{textgray}$\blacksquare$\enspace Other\hspace{24pt}%
    \color{textgray}Scoring: Total Score = Stars Score + Forks Score + Base Score%
  }
  \end{tabular}
}

% ══════════════════════════════════════════════════════
%  LANGUAGE BREAKDOWN
% ══════════════════════════════════════════════════════
\posterbox[
  greencard, title={Language Distribution},
]{name=language, column=1, between=row13 and row19}{
  \centering\vspace{4pt}
  \begin{tikzpicture}
    % Python - 35% (7 repos)
    \fill[secondary, rounded corners=2pt] (0,0) rectangle (5.6,0.7);
    \node[anchor=west, text=textwhite, font=\fontsize{22}{28}\selectfont\bfseries] at (0.15,0.35) {Python};
    \node[anchor=east, text=textwhite, font=\fontsize{20}{26}\selectfont] at (5.45,0.35) {7 repos --- 35\%};
    % TypeScript - 25% (5 repos)
    \fill[accent, rounded corners=2pt] (0,-1.0) rectangle (4.0,0.7-1.0);
    \node[anchor=west, text=textwhite, font=\fontsize{22}{28}\selectfont\bfseries] at (0.15,0.35-1.0) {TypeScript};
    \node[anchor=east, text=textwhite, font=\fontsize{20}{26}\selectfont] at (3.85,0.35-1.0) {5 repos --- 25\%};
    % Rust - 10% (2 repos)
    \fill[highlight, rounded corners=2pt] (0,-2.0) rectangle (1.6,0.7-2.0);
    \node[anchor=west, text=textwhite, font=\fontsize{22}{28}\selectfont\bfseries] at (0.15,0.35-2.0) {Rust};
    \node[anchor=east, text=primary, font=\fontsize{20}{26}\selectfont] at (1.5,0.35-2.0) {2 --- 10\%};
    % Others - 30% (6 repos)
    \fill[textgray, rounded corners=2pt] (0,-3.0) rectangle (4.8,0.7-3.0);
    \node[anchor=west, text=textwhite, font=\fontsize{22}{28}\selectfont\bfseries] at (0.15,0.35-3.0) {Others};
    \node[anchor=east, text=textwhite, font=\fontsize{20}{26}\selectfont] at (4.65,0.35-3.0) {6 repos --- 30\%};
  \end{tikzpicture}
  \vspace{8pt}

  \colorbox{accent!20!primary}{\parbox{0.92\linewidth}{%
    \centering\vspace{4pt}%
    {\fontsize{22}{28}\selectfont\color{accent}\bfseries Python + TypeScript = 60\% of trending repos}%
    \vspace{4pt}%
  }}
  \vspace{6pt}

  {\fontsize{20}{26}\selectfont\color{textgray}%
    Verilog, HTML, JavaScript, Dart, Shell each contribute 1 project.%
  }
}

% ══════════════════════════════════════════════════════
%  KEY THEMES
% ══════════════════════════════════════════════════════
\posterbox[
  ambercard, title={Key Themes: AI Agents Lead the Wave},
]{name=themes, column=2, span=2, between=row13 and row19}{
  \fontsize{26}{34}\selectfont\color{textwhite}%

  \colorbox{secondary!25!primary}{\parbox{0.95\linewidth}{%
    \vspace{4pt}\fontsize{26}{34}\selectfont%
    \color{secondary}\bfseries $\blacktriangleright$ Autonomous Coding Agents\\[2pt]
    \color{textgray}\fontsize{24}{32}\selectfont
    multica, open-agents, GenericAgent --- AI writes code, handles issues, executes tasks autonomously\vspace{4pt}
  }}\\[8pt]

  \colorbox{highlight!25!primary}{\parbox{0.95\linewidth}{%
    \vspace{4pt}\fontsize{26}{34}\selectfont%
    \color{highlight}\bfseries $\blacktriangleright$ Token Optimization\\[2pt]
    \color{textgray}\fontsize{24}{32}\selectfont
    caveman, rtk --- Slash LLM token consumption by 60--90\%, cutting cost and latency\vspace{4pt}
  }}\\[8pt]

  \colorbox{accent!25!primary}{\parbox{0.95\linewidth}{%
    \vspace{4pt}\fontsize{26}{34}\selectfont%
    \color{accent}\bfseries $\blacktriangleright$ Memory \& Context Management\\[2pt]
    \color{textgray}\fontsize{24}{32}\selectfont
    claude-mem, graphify --- Capture, compress, and query coding sessions and codebases\vspace{4pt}
  }}\\[8pt]

  \colorbox{secondary!15!primary}{\parbox{0.95\linewidth}{%
    \vspace{4pt}\fontsize{26}{34}\selectfont%
    \color{secondary}\bfseries $\blacktriangleright$ Skill Distillation\\[2pt]
    \color{textgray}\fontsize{24}{32}\selectfont
    andrej-karpathy-skills (\#1 repo), nuwa-skill --- Package expert mental models as reusable AI skills\vspace{4pt}
  }}
}

% ══════════════════════════════════════════════════════
%  FOOTER
% ══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!95!black, boxrule=0pt, arc=0pt,
  left=30pt, right=30pt, top=8pt, bottom=8pt,
  valign=center, halign=center,
]{name=footer, column=1, span=3, between=row19 and row20}{
  {\fontsize{22}{28}\selectfont\color{textgray}%
    Source: OSSInsight\enspace$\bullet$\enspace
    Scoring: Stars Score + Forks Score + Base Score\enspace$\bullet$\enspace
    Data Window: Past 24 Hours\enspace$\bullet$\enspace
    Total Stars Across Top 10: 3,254%
  }
}

\end{tcbposter}
\end{document}

